file.content:
#page_total.onscroll .page_header:not(.menu_open) {transform: translate(0,-68px);}

.page_header.menu_open{ position: fixed; z-index: 200; }
.page_header .ph_container {
	width: 81.95%;
	height: 100%;
	margin: 0 auto;
	z-index: 3;

}
	.page_header .ph_container > * 
	,.page_header .ph_menu_opener.mobile 
	{ transition: transform .5s; }
	#page_total.onscroll .page_header:not(.menu_open) .ph_container .ph_menu_opener
	,#page_total.onscroll .page_header:not(.menu_open) .ph_menu_opener.mobile
	{transform: translate(0,33px);}

	#page_total.onscroll .page_header:not(.menu_open) .ph_container .ph_main_menu {transform: translate(0,-20px);}

	/* Logo
	------------------------------------------------------------------------------------------ */
	h3.logo{ 
		width: 145px; 
		height: auto; 
		margin: 45px 0 0 0; 
		float: left; 
		transition-duration: 0.4s;
		#payoff{
			transition: opacity .3s ease-in-out;
		}
	}
		//allo scroll
		#page_total.onscroll .page_header:not(.menu_open) .ph_container .logo{
			transform: translateY(45px);
			#payoff{
				opacity: 0;
			}
		}


	/* Hamburger - solo dimensioni e posizione
	------------------------------------------------------------------------------------------ */
	.ph_menu_opener{
		width: 30px;
		height: 30px;
		margin-top: 49px;
		float: right;
		transition-duration: 0.4s;
	}
	.ph_menu_opener.mobile{ display: none; }

